import os, requests, urllib.parse
with open(os.environ['GALAXY_API_KEY_FILE']) as f: key=f.read().strip()
url='https://usegalaxy.org'
for tid in ['toolshed.g2.bx.psu.edu/repos/devteam/bowtie2/bowtie2/2.5.5+galaxy0','toolshed.g2.bx.psu.edu/repos/iuc/hisat2/hisat2/2.2.2+galaxy0']:
    j=requests.get(url+'/api/tools/'+urllib.parse.quote(tid,safe=''), params={'key':key,'io_details':'true'}, timeout=30).json()
    vals=[]
    def walk(inputs):
        for inp in inputs:
            if inp.get('model_class')=='Conditional':
                for c in inp.get('cases',[]): walk(c.get('inputs',[]))
            elif inp.get('model_class') in ('Section','Repeat'):
                walk(inp.get('inputs',[]))
            elif inp.get('name')=='index' and inp.get('options'):
                for label,val,sel in inp['options']:
                    l=label.lower(); v=val.lower()
                    if any(s in l or s in v for s in ['homo','human','hg19','hg38','grch37','grch38']):
                        vals.append((label,val,sel))
    walk(j.get('inputs',[]))
    print('\\n',j.get('name'), len(vals))
    for x in vals[:50]: print(x)
PY"

